{"file_path":"src/parser.js","content":"/**
 * Addresses and the sheet input format.
 *
 * A column is one or two letters, `A`..`Z` then `AA`..`ZZ`; a row is one to
 * three digits and is at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Column label to its zero based index, or -1 when the label is not one. */
export function colToNum(col) {
  const A = 'A'.charCodeAt(0)
  if (col.length === 1) return col.charCodeAt(0) - A
  if (col.length === 2) return 26 + (col.charCodeAt(0) - A) * 26 + (col.charCodeAt(1) - A)
  return -1
}

/** Zero based column index back to its label. */
export function numToCol(n) {
  const A = 'A'.charCodeAt(0)
  if (n < 26) return String.fromCharCode(A + n)
  const rest = n - 26
  return String.fromCharCode(A + Math.floor(rest / 26)) + String.fromCharCode(A + (rest % 26))
}

/**
 * Read a word as an address inside the addressable range. Returns
 * `{ col, row }` with the column upper cased, or null when the word does not
 * name a cell that exists.
 */
export function parseAddress(word) {
  const match = ADDRESS_RE.exec(word)
  if (!match) return null

  const col = match[1].toUpperCase()
  const row = parseInt(match[2], 10)
  if (row < 1) return null

  return { col, row }
}

export function addressToString(col, row) {
  return `${col}${row}`
}

/** Order two addresses by column and then by row. */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  const ca = colToNum(pa.col)
  const cb = colToNum(pb.col)
  if (ca !== cb) return ca - cb
  return pa.row - pb.row
}

/**
 * Split a sheet into its declared cells, keyed by upper cased address, in the
 * order the lines declare them. Throws with the message to report on the first
 * bad line.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    const breakAt = line.search(/[ \t]/)
    const word = breakAt === -1 ? line : line.slice(0, breakAt)

    const address = parseAddress(word)
    if (!address) {
      throw new Error(`error: line ${lineNumber}: invalid cell address ${word}`)
    }

    const key = addressToString(address.col, address.row)
    if (cells.has(key)) {
      throw new Error(`error: line ${lineNumber}: cell ${key} is declared twice`)
    }

    let content = ''
    if (breakAt !== -1) {
      let start = breakAt
      while (start < line.length && (line[start] === ' ' || line[start] === '\t')) start++
      content = line.slice(start)
    }

    cells.set(key, { col: address.col, row: address.row, content })
  }

  return cells
}
"}

