{"file_path":"src/formula.js","content":"/**
 * The formula grammar: a tokenizer and a recursive descent parser producing an
 * abstract syntax tree. Anything the grammar does not accept is reported by
 * throwing `SyntaxFailure`, which the caller turns into `#ERR!`.
 */

export class SyntaxFailure extends Error {}

function fail() {
  throw new SyntaxFailure('grammar')
}

const SIMPLE = {
  '(': 'lparen',
  ')': 'rparen',
  ',': 'comma',
  ':': 'colon',
  '+': 'plus',
  '-': 'minus',
  '*': 'mul',
  '/': 'div',
  '^': 'pow',
  '=': 'eq'
}

function tokenize(source) {
  const tokens = []
  let pos = 0

  while (pos < source.length) {
    const ch = source[pos]

    if (ch === ' ' || ch === '\t') {
      pos++
      continue
    }

    if (ch >= '0' && ch <= '9') {
      const match = /^[0-9]+(\.[0-9]+)?/.exec(source.slice(pos))
      pos += match[0].length
      // A second point, or a point with no digits behind it, is not a number.
      if (source[pos] === '.') fail()
      tokens.push({ type: 'number', value: parseFloat(match[0]) })
      continue
    }

    if (/[A-Za-z]/.test(ch)) {
      const match = /^[A-Za-z][A-Za-z0-9]*/.exec(source.slice(pos))
      pos += match[0].length
      const word = match[0].toUpperCase()
      if (word === 'TRUE') tokens.push({ type: 'boolean', value: true })
      else if (word === 'FALSE') tokens.push({ type: 'boolean', value: false })
      else tokens.push({ type: 'word', value: word })
      continue
    }

    if (ch === '<') {
      pos++
      if (source[pos] === '=') {
        pos++
        tokens.push({ type: 'le' })
      } else if (source[pos] === '>') {
        pos++
        tokens.push({ type: 'ne' })
      } else {
        tokens.push({ type: 'lt' })
      }
      continue
    }

    if (ch === '>') {
      pos++
      if (source[pos] === '=') {
        pos++
        tokens.push({ type: 'ge' })
      } else {
        tokens.push({ type: 'gt' })
      }
      continue
    }

    const simple = SIMPLE[ch]
    if (!simple) fail()
    pos++
    tokens.push({ type: simple })
  }

  return tokens
}

const COMPARISONS = ['eq', 'ne', 'lt', 'le', 'gt', 'ge']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  at(type) {
    const token = this.peek()
    return token !== null && token.type === type
  }

  take(type) {
    if (!this.at(type)) fail()
    return this.tokens[this.pos++]
  }

  parseFormula() {
    const expr = this.parseComparison()
    if (this.peek() !== null) fail()
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && COMPARISONS.includes(this.peek().type)) {
      const op = this.tokens[this.pos++].type
      const right = this.parseAdditive()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.at('plus') || this.at('minus')) {
      const op = this.tokens[this.pos++].type
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.at('mul') || this.at('div')) {
      const op = this.tokens[this.pos++].type
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.at('pow')) {
      this.pos++
      const right = this.parsePower()
      return { type: 'binary', op: 'pow', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('plus') || this.at('minus')) {
      const op = this.tokens[this.pos++].type
      return { type: 'unary', op, expr: this.parseUnary() }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (token === null) fail()

    if (token.type === 'lparen') {
      this.pos++
      const expr = this.parseComparison()
      this.take('rparen')
      // Wrapped, so a range inside parentheses is no longer an argument.
      return { type: 'paren', expr }
    }

    if (token.type === 'number') {
      this.pos++
      return { type: 'number', value: token.value }
    }

    if (token.type === 'boolean') {
      this.pos++
      return { type: 'boolean', value: token.value }
    }

    if (token.type === 'word') {
      this.pos++

      if (this.at('lparen')) {
        this.pos++
        const args = []
        if (!this.at('rparen')) {
          args.push(this.parseComparison())
          while (this.at('comma')) {
            this.pos++
            args.push(this.parseComparison())
          }
        }
        this.take('rparen')
        return { type: 'call', name: token.value, args }
      }

      if (this.at('colon')) {
        this.pos++
        const end = this.take('word')
        return { type: 'range', from: token.value, to: end.value }
      }

      return { type: 'address', name: token.value }
    }

    return fail()
  }
}

/** Parse a formula body, throwing `SyntaxFailure` when the grammar rejects it. */
export function parseFormula(source) {
  return new Parser(tokenize(source)).parseFormula()
}
"}

