      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return error(ERR)
    }
  }

  binary(node) {
    const left = this.node(node.left)
    if (isError(left)) return left
    const right = this.node(node.right)
    if (isError(right)) return right

    switch (node.op) {
      case 'eq':
        return boolean(compareValues(left, right) === 0)
      case 'ne':
        return boolean(compareValues(left, right) !== 0)
      case 'lt':
        return boolean(compareValues(left, right) < 0)
      case 'le':
        return boolean(compareValues(left, right) <= 0)
      case 'gt':
        return boolean(compareValues(left, right) > 0)
      case 'ge':
        return boolean(compareValues(left, right) >= 0)
    }

    const a = asNumber(left)
    if (isError(a)) return a
    const b = asNumber(right)
    if (isError(b)) return b

    switch (node.op) {
      case 'plus':
        return finite(a.value + b.value)
      case 'minus':
        return finite(a.value - b.value)
      case 'mul':
        return finite(a.value * b.value)
      case 'div':
        if (b.value === 0) return error(DIV0)
        return finite(a.value / b.value)
      case 'pow':
        return finite(Math.pow(a.value, b.value))
      default:
        return error(ERR)
    }
  }

  /** The values an argument contributes, a range covering every cell it spans. */
  argument(node) {
    if (node.type === 'range') {
      const cells = rangeCells(node)
      if (!cells) return [error(REF)]
      return cells.map(address => this.cell(address))
    }
    return [this.node(node)]
  }

  call(node) {
    if (!Object.prototype.hasOwnProperty.call(ARITY, node.name)) return error(NAME)

    const arity = ARITY[node.name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return error(ERR)

    if (node.name === 'IF') return this.callIf(node.args)

    const values = []
    for (const arg of node.args) values.push(...this.argument(arg))

    // An error among the arguments wins over anything the call would report.
    for (const value of values) {
      if (isError(value)) return value
    }

    if (node.name === 'COUNT') {
      return number(values.filter(value => value.kind === 'number').length)
    }

    const numbers = []
    for (const value of values) {
      const converted = asNumber(value)
      if (isError(converted)) return converted
      numbers.push(converted.value)
    }

    switch (node.name) {
      case 'SUM':
        return finite(numbers.reduce((total, value) => total + value, 0))
      case 'MIN':
        return finite(numbers.reduce((best, value) => Math.min(best, value)))
      case 'MAX':
        return finite(numbers.reduce((best, value) => Math.max(best, value)))
      case 'AVG':
