/**
 * Parse and evaluate formulas in cells.
 */

import { parseAddress, addressToString } from './parser.js'

const ERROR_DIV_ZERO = '#DIV/0!'
const ERROR_REF = '#REF!'
const ERROR_VALUE = '#VALUE!'
const ERROR_CYCLE = '#CYCLE!'
const ERROR_NAME = '#NAME?'
const ERROR_ERR = '#ERR!'

const ERRORS = new Set([ERROR_DIV_ZERO, ERROR_REF, ERROR_VALUE, ERROR_CYCLE, ERROR_NAME, ERROR_ERR])

class Value {
  constructor(type, val) {
    this.type = type // 'number', 'text', 'boolean', 'error'
    this.val = val
  }

  static number(n) {
    return new Value('number', n)
  }

  static text(s) {
    return new Value('text', s)
  }

  static boolean(b) {
    return new Value('boolean', b)
  }

  static error(e) {
    return new Value('error', e)
  }

  static zero() {
    return new Value('number', 0)
  }

  isError() {
    return this.type === 'error'
  }

  asNumber() {
    if (this.type === 'number') return Value.number(this.val)
    if (this.type === 'boolean') return Value.number(this.val ? 1 : 0)
    if (this.type === 'text') return Value.error(ERROR_VALUE)
    if (this.type === 'error') return this
    return Value.error(ERROR_ERR)
  }

  asBoolean() {
    if (this.type === 'boolean') return this.val
    if (this.type === 'number') return this.val !== 0
    if (this.type === 'error') return this
    // text is always true
    return true
  }
}

function parseContent(content) {
  if (content === '') return Value.zero()

  if (content.startsWith('=')) {
    return { type: 'formula', formula: content.substring(1) }
  }

  // Check if it's an error
  if (ERRORS.has(content)) {
    return Value.error(content)
  }

  // Check if it's a number
  if (/^-?\d+(\.\d+)?$/.test(content)) {
    return Value.number(parseFloat(content))
  }

  // Check if it's a boolean
  if (content === 'TRUE') return Value.boolean(true)
  if (content === 'FALSE') return Value.boolean(false)

  // Otherwise it's text
  return Value.text(content)
}

class Tokenizer {
  constructor(input) {
    this.input = input
    this.pos = 0
  }

  skipWhitespace() {
    while (this.pos < this.input.length && /[ \t]/.test(this.input[this.pos])) {
      this.pos++
    }
  }

  peek() {
    this.skipWhitespace()
    return this.pos < this.input.length ? this.input[this.pos] : null
  }

  peekN(n) {
    let tmp = this.pos
    this.skipWhitespace()
    let result = ''
    while (n-- > 0 && this.pos < this.input.length) {
      result += this.input[this.pos++]
    }
    this.pos = tmp
    return result
  }

  next() {
    this.skipWhitespace()
    if (this.pos >= this.input.length) return null

    const ch = this.input[this.pos]

    // Numbers
    if (/\d/.test(ch)) {
      let num = ''
      while (this.pos < this.input.length && /[\d.]/.test(this.input[this.pos])) {
        num += this.input[this.pos++]
      }
      return { type: 'number', val: parseFloat(num) }
    }

    // Cell addresses or keywords (letters)
    if (/[A-Za-z]/.test(ch)) {
      let word = ''
      while (this.pos < this.input.length && /[A-Za-z0-9]/.test(this.input[this.pos])) {
        word += this.input[this.pos++]
      }
      const upper = word.toUpperCase()
      if (upper === 'TRUE') return { type: 'boolean', val: true }
      if (upper === 'FALSE') return { type: 'boolean', val: false }
      if (/^[A-Z]{1,2}\d{1,3}$/.test(upper)) return { type: 'address', val: upper }
      return { type: 'name', val: upper }
    }

    // Operators and punctuation
    if (ch === ':') {
      this.pos++
      return { type: 'colon' }
    }
    if (ch === '(') {
      this.pos++
      return { type: 'lparen' }
    }
    if (ch === ')') {
      this.pos++
      return { type: 'rparen' }
    }
    if (ch === ',') {
      this.pos++
      return { type: 'comma' }
    }
    if (ch === '+') {
      this.pos++
      return { type: 'plus' }
    }
    if (ch === '-') {
      this.pos++
      return { type: 'minus' }
    }
    if (ch === '*') {
      this.pos++
      return { type: 'mul' }
    }
    if (ch === '/') {
      this.pos++
      return { type: 'div' }
    }
    if (ch === '^') {
      this.pos++
      return { type: 'pow' }
    }
    if (ch === '=') {
      this.pos++
      return { type: 'eq' }
    }
    if (ch === '<') {
      this.pos++
      if (this.pos < this.input.length && this.input[this.pos] === '=') {
        this.pos++
        return { type: 'lte' }
      }
      if (this.pos < this.input.length && this.input[this.pos] === '>') {
        this.pos++
        return { type: 'neq' }
      }
      return { type: 'lt' }
    }
    if (ch === '>') {
      this.pos++
      if (this.pos < this.input.length && this.input[this.pos] === '=') {
        this.pos++
        return { type: 'gte' }
      }
      return { type: 'gt' }
    }

    // Unknown character
    return null
  }
}

class Parser {
  constructor(formula) {
    this.tokenizer = new Tokenizer(formula)
    this.current = this.tokenizer.next()
  }

  advance() {
    this.current = this.tokenizer.next()
  }

  expect(type) {
    if (!this.current || this.current.type !== type) {
      throw new Error(ERROR_ERR)
    }
    const token = this.current
    this.advance()
    return token
  }

  parse() {
    const expr = this.parseComparison()
    if (this.current !== null) {
      throw new Error(ERROR_ERR)
    }
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.current && ['eq', 'neq', 'lt', 'lte', 'gt', 'gte'].includes(this.current.type)) {
      const op = this.current.type
      this.advance()
      const right = this.parseAdditive()
      left = { type: 'comparison', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.current && ['plus', 'minus'].includes(this.current.type)) {
      const op = this.current.type
      this.advance()
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.current && ['mul', 'div'].includes(this.current.type)) {
      const op = this.current.type
      this.advance()
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    let left = this.parseUnary()
    if (this.current && this.current.type === 'pow') {
      this.advance()
      const right = this.parsePower() // Right associative
      left = { type: 'binary', op: 'pow', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.current && ['plus', 'minus'].includes(this.current.type)) {
      const op = this.current.type
      this.advance()
      const expr = this.parseUnary()
      return { type: 'unary', op, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    if (!this.current) {
      throw new Error(ERROR_ERR)
    }

    if (this.current.type === 'lparen') {
      this.advance()
      const expr = this.parseComparison()
      this.expect('rparen')
      return expr
    }

    if (this.current.type === 'number') {
      const val = this.current.val
      this.advance()
      return { type: 'number', val }
    }

    if (this.current.type === 'boolean') {
      const val = this.current.val
      this.advance()
      return { type: 'boolean', val }
    }

    if (this.current.type === 'address') {
      const addr = this.current.val
      this.advance()

      // Check for range
      if (this.current && this.current.type === 'colon') {
        this.advance()
        if (!this.current || this.current.type !== 'address') {
          throw new Error(ERROR_ERR)
        }
        const addr2 = this.current.val
        this.advance()
        return { type: 'range', addr1: addr, addr2 }
      }

      return { type: 'address', val: addr }
    }

    if (this.current.type === 'name') {
      const name = this.current.val
      this.advance()

      // Function call
      if (this.current && this.current.type === 'lparen') {
        this.advance()
        const args = []
        if (this.current && this.current.type !== 'rparen') {
          args.push(this.parseComparison())
          while (this.current && this.current.type === 'comma') {
            this.advance()
            args.push(this.parseComparison())
          }
        }
        this.expect('rparen')
        return { type: 'call', name, args }
      }

      // Bare name is treated as address but invalid
      return { type: 'address', val: name }
    }

    throw new Error(ERROR_ERR)
  }
}

class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.evaluating = new Set()
  }

  evaluate(addr) {
    if (this.cache.has(addr)) {
      return this.cache.get(addr)
    }

    if (this.evaluating.has(addr)) {
      return Value.error(ERROR_CYCLE)
    }

    this.evaluating.add(addr)

    const cell = this.cells.get(addr)
    let result

    if (!cell) {
      result = Value.zero()
    } else {
      const content = parseContent(cell.content)
      if (content.type === 'formula') {
        try {
          const parser = new Parser(content.formula)
          const ast = parser.parse()
          result = this.evaluateAst(ast)
        } catch (e) {
          result = Value.error(e.message.startsWith('#') ? e.message : ERROR_ERR)
        }
      } else {
        result = content
      }
    }

    this.evaluating.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  evaluateAst(node) {
    if (!node) return Value.error(ERROR_ERR)

    if (node.type === 'number') {
      return Value.number(node.val)
    }

    if (node.type === 'boolean') {
      return Value.boolean(node.val)
    }

    if (node.type === 'address') {
      const parsed = parseAddress(node.val)
      if (!parsed) {
        return Value.error(ERROR_REF)
      }
      const addr = addressToString(parsed.col, parsed.row)
      return this.evaluate(addr)
    }

    if (node.type === 'range') {
      return Value.error(ERROR_ERR) // Ranges should only appear as function arguments
    }

    if (node.type === 'binary') {
      const left = this.evaluateAst(node.left)
      if (left.isError()) return left

      const right = this.evaluateAst(node.right)
      if (right.isError()) return right

      return this.evaluateBinary(node.op, left, right)
    }

    if (node.type === 'comparison') {
      const left = this.evaluateAst(node.left)
      if (left.isError()) return left

      const right = this.evaluateAst(node.right)
      if (right.isError()) return right

      return this.evaluateComparison(node.op, left, right)
    }

    if (node.type === 'unary') {
      const expr = this.evaluateAst(node.expr)
      if (expr.isError()) return expr

      if (node.op === 'minus') {
        const num = expr.asNumber()
        if (num.isError()) return num
        return Value.number(-num.val)
      } else { // plus
        const num = expr.asNumber()
        if (num.isError()) return num
        return Value.number(num.val)
      }
    }

    if (node.type === 'call') {
      return this.evaluateCall(node.name, node.args)
    }

    return Value.error(ERROR_ERR)
  }

  evaluateBinary(op, left, right) {
    if (op === 'plus') {
      const l = left.asNumber()
      if (l.isError()) return l
      const r = right.asNumber()
      if (r.isError()) return r
      const result = l.val + r.val
      if (!isFinite(result)) return Value.error(ERROR_DIV_ZERO)
      return Value.number(result)
    }

    if (op === 'minus') {
      const l = left.asNumber()
      if (l.isError()) return l
      const r = right.asNumber()
      if (r.isError()) return r
      const result = l.val - r.val
      if (!isFinite(result)) return Value.error(ERROR_DIV_ZERO)
      return Value.number(result)
    }

    if (op === 'mul') {
      const l = left.asNumber()
      if (l.isError()) return l
      const r = right.asNumber()
      if (r.isError()) return r
      const result = l.val * r.val
      if (!isFinite(result)) return Value.error(ERROR_DIV_ZERO)
      return Value.number(result)
    }

    if (op === 'div') {
      const l = left.asNumber()
      if (l.isError()) return l
      const r = right.asNumber()
      if (r.isError()) return r
      if (r.val === 0) return Value.error(ERROR_DIV_ZERO)
      const result = l.val / r.val
      if (!isFinite(result)) return Value.error(ERROR_DIV_ZERO)
      return Value.number(result)
    }

    if (op === 'pow') {
      const l = left.asNumber()
      if (l.isError()) return l
      const r = right.asNumber()
      if (r.isError()) return r
      const result = Math.pow(l.val, r.val)
      if (!isFinite(result)) return Value.error(ERROR_DIV_ZERO)
      return Value.number(result)
    }

    return Value.error(ERROR_ERR)
  }

  evaluateComparison(op, left, right) {
    // Determine types and convert if needed
    let cmp
    if (left.type === 'number' && right.type === 'number') {
      cmp = left.val < right.val ? -1 : left.val > right.val ? 1 : 0
    } else if (left.type === 'text' && right.type === 'text') {
      cmp = left.val < right.val ? -1 : left.val > right.val ? 1 : 0
    } else if (left.type === 'boolean' && right.type === 'boolean') {
      cmp = (left.val ? 1 : 0) < (right.val ? 1 : 0) ? -1 : (left.val ? 1 : 0) > (right.val ? 1 : 0) ? 1 : 0
    } else {
      // Different types: number < text < boolean
      const order = { number: 0, text: 1, boolean: 2 }
      const lo = order[left.type]
      const ro = order[right.type]
      cmp = lo < ro ? -1 : lo > ro ? 1 : 0
    }

    let result
    if (op === 'eq') result = cmp === 0
    else if (op === 'neq') result = cmp !== 0
    else if (op === 'lt') result = cmp < 0
    else if (op === 'lte') result = cmp <= 0
    else if (op === 'gt') result = cmp > 0
    else if (op === 'gte') result = cmp >= 0
    else return Value.error(ERROR_ERR)

    return Value.boolean(result)
  }

  getRangeValues(node) {
    if (node.type === 'range') {
      const p1 = parseAddress(node.addr1)
      const p2 = parseAddress(node.addr2)
      if (!p1 || !p2) return []

      const col1 = p1.col.charCodeAt(0) - 'A'.charCodeAt(0)
      const col2 = p2.col.charCodeAt(0) - 'A'.charCodeAt(0)
      let c1, c2

      if (p1.col.length === 2) {
        c1 = 26 + (p1.col.charCodeAt(1) - 'A'.charCodeAt(0))
      } else {
        c1 = col1
      }

      if (p2.col.length === 2) {
        c2 = 26 + (p2.col.charCodeAt(1) - 'A'.charCodeAt(0))
      } else {
        c2 = col2
      }

      const minC = Math.min(c1, c2)
      const maxC = Math.max(c1, c2)
      const minR = Math.min(p1.row, p2.row)
      const maxR = Math.max(p1.row, p2.row)

      const values = []
      for (let c = minC; c <= maxC; c++) {
        for (let r = minR; r <= maxR; r++) {
          const col = c < 26 ? String.fromCharCode(c + 'A'.charCodeAt(0)) : 'A' + String.fromCharCode(c - 26 + 'A'.charCodeAt(0))
          const addr = col + r
          values.push(this.evaluate(addr))
        }
      }
      return values
    }

    return [this.evaluateAst(node)]
  }

  evaluateCall(name, args) {
    if (name === 'SUM') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      const values = []
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        values.push(...v)
      }
      let sum = 0
      for (const val of values) {
        const num = val.asNumber()
        if (num.isError()) return num
        sum += num.val
      }
      return Value.number(sum)
    }

    if (name === 'MIN') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let min = Infinity
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          min = Math.min(min, num.val)
        }
      }
      return Value.number(min === Infinity ? 0 : min)
    }

    if (name === 'MAX') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let max = -Infinity
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          max = Math.max(max, num.val)
        }
      }
      return Value.number(max === -Infinity ? 0 : max)
    }

    if (name === 'COUNT') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let count = 0
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        for (const val of v) {
          if (val.isError()) continue
          if (val.type === 'number') count++
        }
      }
      return Value.number(count)
    }

    if (name === 'AVG') {
      if (args.length === 0) return Value.error(ERROR_ERR)
      let sum = 0
      let count = 0
      for (const arg of args) {
        const v = this.getRangeValues(arg)
        if (v.some(x => x.isError())) {
          for (const val of v) {
            if (val.isError()) return val
          }
        }
        for (const val of v) {
          const num = val.asNumber()
          if (num.isError()) return num
          sum += num.val
          count++
        }
      }
      if (count === 0) return Value.number(0)
      return Value.number(sum / count)
    }

    if (name === 'ABS') {
      if (args.length !== 1) return Value.error(ERROR_ERR)
      const val = this.evaluateAst(args[0])
      if (val.isError()) return val
      const num = val.asNumber()
      if (num.isError()) return num
      return Value.number(Math.abs(num.val))
    }

    if (name === 'IF') {
      if (args.length !== 3) return Value.error(ERROR_ERR)
      const cond = this.evaluateAst(args[0])
      if (cond.isError()) return cond
      const isTruthy = cond.type === 'boolean' ? cond.val : cond.type === 'number' ? cond.val !== 0 : true
      if (isTruthy) {
        return this.evaluateAst(args[1])
      } else {
        return this.evaluateAst(args[2])
      }
    }

    return Value.error(ERROR_NAME)
  }
}

export function evaluateSheet(cells) {
  const evaluator = new Evaluator(cells)
  const result = new Map()

  for (const [addr, cell] of cells) {
    result.set(addr, evaluator.evaluate(addr))
  }

  return result
}

export function getDependencies(cells) {
  const deps = new Map() // addr -> Set of addresses

  for (const [addr, cell] of cells) {
    const content = parseContent(cell.content)
    if (content.type === 'formula') {
      try {
        const parser = new Parser(content.formula)
        const ast = parser.parse()
        const cellDeps = new Set()
        collectDependencies(ast, cellDeps)
        deps.set(addr, cellDeps)
      } catch (e) {
        deps.set(addr, new Set())
      }
    } else {
      deps.set(addr, new Set())
    }
  }

  return deps
}

function collectDependencies(node, deps) {
  if (!node) return

  if (node.type === 'address') {
    const parsed = parseAddress(node.val)
    if (parsed) {
      const addr = addressToString(parsed.col, parsed.row)
      deps.add(addr)
    }
    return
  }

  if (node.type === 'range') {
    const p1 = parseAddress(node.addr1)
    const p2 = parseAddress(node.addr2)
    if (p1 && p2) {
      const col1 = p1.col.charCodeAt(0) - 'A'.charCodeAt(0) + (p1.col.length === 2 ? 26 : 0)
      const col2 = p2.col.charCodeAt(0) - 'A'.charCodeAt(0) + (p2.col.length === 2 ? 26 : 0)
      const minC = Math.min(col1, col2)
      const maxC = Math.max(col1, col2)
      const minR = Math.min(p1.row, p2.row)
      const maxR = Math.max(p1.row, p2.row)

      for (let c = minC; c <= maxC; c++) {
        for (let r = minR; r <= maxR; r++) {
          const col = c < 26 ? String.fromCharCode(c + 'A'.charCodeAt(0)) : 'A' + String.fromCharCode(c - 26 + 'A'.charCodeAt(0))
          const addr = col + r
          deps.add(addr)
        }
      }
    }
    return
  }

  if (node.type === 'binary' || node.type === 'comparison') {
    collectDependencies(node.left, deps)
    collectDependencies(node.right, deps)
    return
  }

  if (node.type === 'unary') {
    collectDependencies(node.expr, deps)
    return
  }

  if (node.type === 'call') {
    for (const arg of node.args) {
      collectDependencies(arg, deps)
    }
    return
  }
}

