/**
 * Values, and the evaluation of the cells that hold them.
 */

import { parseAddress, addressToString, colToNum, numToCol } from './parser.js'
import { parseFormula, SyntaxFailure } from './formula.js'

export const DIV0 = '#DIV/0!'
export const REF = '#REF!'
export const VALUE = '#VALUE!'
export const CYCLE = '#CYCLE!'
export const NAME = '#NAME?'
export const ERR = '#ERR!'

const ERROR_TOKENS = new Set([DIV0, REF, VALUE, CYCLE, NAME, ERR])

export const number = value => ({ kind: 'number', value })
export const text = value => ({ kind: 'text', value })
export const boolean = value => ({ kind: 'boolean', value })
export const error = value => ({ kind: 'error', value })

const isError = value => value.kind === 'error'

/** A cell's content as a literal value, or the formula body it holds. */
function readContent(content) {
  if (content.startsWith('=')) return { formula: content.slice(1) }
  if (content === '') return { value: number(0) }
  if (ERROR_TOKENS.has(content)) return { value: error(content) }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return { value: number(parseFloat(content)) }
  return { value: text(content) }
}

/** A value in an arithmetic position: booleans count, text does not. */
function asNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return number(value.value ? 1 : 0)
  if (value.kind === 'error') return value
  return error(VALUE)
}

/** Guard every arithmetic result: an infinite or undefined one is a failure. */
function finite(result) {
  return Number.isFinite(result) ? number(result) : error(DIV0)
}

/** Compare two texts by code point rather than by UTF-16 code unit. */
function compareText(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i++) {
    const ca = left[i].codePointAt(0)
    const cb = right[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

const KIND_ORDER = { number: 0, text: 1, boolean: 2 }

function compareValues(left, right) {
  if (left.kind !== right.kind) {
    return KIND_ORDER[left.kind] < KIND_ORDER[right.kind] ? -1 : 1
  }
  if (left.kind === 'number') {
    if (left.value === right.value) return 0
    return left.value < right.value ? -1 : 1
  }
  if (left.kind === 'text') return compareText(left.value, right.value)
  const a = left.value ? 1 : 0
  const b = right.value ? 1 : 0
  return a === b ? 0 : a < b ? -1 : 1
}

/** The addresses a range covers, by column and then by row, or null. */
export function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (!from || !to) return null

  const c1 = colToNum(from.col)
  const c2 = colToNum(to.col)
  const minCol = Math.min(c1, c2)
  const maxCol = Math.max(c1, c2)
  const minRow = Math.min(from.row, to.row)
  const maxRow = Math.max(from.row, to.row)

  const cells = []
  for (let c = minCol; c <= maxCol; c++) {
    for (let r = minRow; r <= maxRow; r++) {
      cells.push(addressToString(numToCol(c), r))
    }
  }
  return cells
}

const ARITY = { SUM: null, MIN: null, MAX: null, COUNT: null, AVG: null, ABS: 1, IF: 3 }

class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.active = new Set()
  }

  cell(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    if (this.active.has(address)) return error(CYCLE)

    this.active.add(address)
    let result
    try {
      const declared = this.cells.get(address)
      if (!declared) {
        result = number(0)
      } else {
        const content = readContent(declared.content)
        if (content.formula === undefined) {
          result = content.value
        } else {
          try {
            result = this.node(parseFormula(content.formula))
          } catch (failure) {
            if (!(failure instanceof SyntaxFailure)) throw failure
            result = error(ERR)
          }
        }
      }
    } finally {
      this.active.delete(address)
    }

    this.cache.set(address, result)
    return result
  }

  node(node) {
    switch (node.type) {
      case 'number':
        return number(node.value)
      case 'boolean':
        return boolean(node.value)
      case 'paren':
        return this.node(node.expr)
      case 'address': {
        const address = parseAddress(node.name)
        if (!address) return error(REF)
        return this.cell(addressToString(address.col, address.row))
      }
      case 'range':
        // A range is only a value where it is an argument of a call.
        return error(ERR)
      case 'unary': {
        const operand = asNumber(this.node(node.expr))
        if (isError(operand)) return operand
        return finite(node.op === 'minus' ? -operand.value : operand.value)
      }
      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return error(ERR)
    }
  }

  binary(node) {
    const left = this.node(node.left)
    if (isError(left)) return left
    const right = this.node(node.right)
    if (isError(right)) return right

    switch (node.op) {
      case 'eq':
        return boolean(compareValues(left, right) === 0)
      case 'ne':
        return boolean(compareValues(left, right) !== 0)
      case 'lt':
        return boolean(compareValues(left, right) < 0)
      case 'le':
        return boolean(compareValues(left, right) <= 0)
      case 'gt':
        return boolean(compareValues(left, right) > 0)
      case 'ge':
        return boolean(compareValues(left, right) >= 0)
    }

    const a = asNumber(left)
    if (isError(a)) return a
    const b = asNumber(right)
    if (isError(b)) return b

    switch (node.op) {
      case 'plus':
        return finite(a.value + b.value)
      case 'minus':
        return finite(a.value - b.value)
      case 'mul':
        return finite(a.value * b.value)
      case 'div':
        if (b.value === 0) return error(DIV0)
        return finite(a.value / b.value)
      case 'pow':
        return finite(Math.pow(a.value, b.value))
      default:
        return error(ERR)
    }
  }

  /** The values an argument contributes, a range covering every cell it spans. */
  argument(node) {
    if (node.type === 'range') {
      const cells = rangeCells(node)
      if (!cells) return [error(REF)]
      return cells.map(address => this.cell(address))
    }
    return [this.node(node)]
  }

  call(node) {
    if (!Object.prototype.hasOwnProperty.call(ARITY, node.name)) return error(NAME)

    const arity = ARITY[node.name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return error(ERR)

    if (node.name === 'IF') return this.callIf(node.args)

    const values = []
    for (const arg of node.args) values.push(...this.argument(arg))

    // An error among the arguments wins over anything the call would report.
    for (const value of values) {
      if (isError(value)) return value
    }

    if (node.name === 'COUNT') {
      return number(values.filter(value => value.kind === 'number').length)
    }

    const numbers = []
    for (const value of values) {
      const converted = asNumber(value)
      if (isError(converted)) return converted
      numbers.push(converted.value)
    }

    switch (node.name) {
      case 'SUM':
        return finite(numbers.reduce((total, value) => total + value, 0))
      case 'MIN':
        return finite(numbers.reduce((best, value) => Math.min(best, value)))
      case 'MAX':
        return finite(numbers.reduce((best, value) => Math.max(best, value)))
      case 'AVG':
        return finite(numbers.reduce((total, value) => total + value, 0) / numbers.length)
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      default:
        return error(ERR)
    }
  }

  callIf(args) {
    const condition = this.argument(args[0])
    for (const value of condition) {
      if (isError(value)) return value
    }

    const test = condition[0]
    let taken
    if (test.kind === 'boolean') taken = test.value
    else if (test.kind === 'number') taken = test.value !== 0
    else return error(VALUE)

    // Only the branch taken is read, so an error in the other one is invisible.
    const branch = this.argument(taken ? args[1] : args[2])
    for (const value of branch) {
      if (isError(value)) return value
    }
    return branch[0]
  }
}

/** Every declared cell's value, keyed by address. */
export function evaluateSheet(cells) {
  const evaluator = new Evaluator(cells)
  const values = new Map()
  for (const address of cells.keys()) values.set(address, evaluator.cell(address))
  return values
}

function collect(node, found) {
  switch (node.type) {
    case 'address': {
      const address = parseAddress(node.name)
      if (address) found.add(addressToString(address.col, address.row))
      return
    }
    case 'range': {
      const cells = rangeCells(node)
      if (cells) for (const address of cells) found.add(address)
      return
    }
    case 'paren':
      collect(node.expr, found)
      return
    case 'unary':
      collect(node.expr, found)
      return
    case 'binary':
      collect(node.left, found)
      collect(node.right, found)
      return
    case 'call':
      for (const arg of node.args) collect(arg, found)
      return
    default:
  }
}

/** The distinct cells each declared cell's content names directly. */
export function sheetDependencies(cells) {
  const dependencies = new Map()

  for (const [address, cell] of cells) {
    const found = new Set()
    const content = readContent(cell.content)
    if (content.formula !== undefined) {
      try {
        collect(parseFormula(content.formula), found)
      } catch (failure) {
        if (!(failure instanceof SyntaxFailure)) throw failure
        found.clear()
      }
    }
    dependencies.set(address, found)
  }

  return dependencies
}

