{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every declared cell
 * of the sheet read from standard input, and `node src/cli.js deps` prints the
 * cells each one names.
 */

import { parseInput } from './parser.js'
import { formatValues, formatDeps } from './formatter.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exitCode = 2
}

const args = process.argv.slice(2)
const mode = args.length === 1 ? args[0] : null

if (mode !== 'values' && mode !== 'deps') {
  fail('error: usage: cli.js values|deps')
} else {
  let input = ''
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', chunk => {
    input += chunk
  })
  process.stdin.on('end', () => {
    try {
      const cells = parseInput(input)
      process.stdout.write(mode === 'values' ? formatValues(cells) : formatDeps(cells))
      process.exitCode = 0
    } catch (error) {
      fail(error.message)
    }
  })
}
"}

