 * Format output for values and deps modes.
 */

import { getDependencies } from './evaluator.js'

function parseAddress(addr) {
  const match = addr.match(/^([A-Za-z]{1,2})(\d{1,3})$/)
  if (!match) return null

  const col = match[1].toUpperCase()
  const row = parseInt(match[2], 10)

  return { col, row }
}

function compareAddresses(a1, a2) {
  const p1 = parseAddress(a1)
  const p2 = parseAddress(a2)
  if (!p1 || !p2) return 0

  const col1 = colToNum(p1.col)
  const col2 = colToNum(p2.col)

  if (col1 !== col2) return col1 - col2
  return p1.row - p2.row
}

function colToNum(col) {
  if (col.length === 1) {
    return col.charCodeAt(0) - 'A'.charCodeAt(0)
  } else {
    return 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
  }
}

