  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', chunk => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    const cells = parseInput(input)
    const sheet = evaluateSheet(cells)
    const output = formatOutputWithCells(sheet, cells, mode)
    process.stdout.write(output)
    process.exit(0)
